def isOneEditApart(s, t):
    if abs(len(s) - len(t)) > 1:
        return False
    if len(s) > len(t):
        s, t = t, s
    i = 0
    while i < len(s) and s[i] == t[i]:
        i += 1
    if i == len(s):
        return len(t) == len(s) + 1
    if len(s) == len(t):
        return s[i + 1:] == t[i + 1:]
    return s[i:] == t[i + 1:]
